import pytest
from pathlib import Path
import json
from validator import SwaggerSchemaValidator

# Constants
TEST_DATA_FILENAME = 'store_inventory.json'
API_SPEC_PATH = 'api.json'

# Load test data
_here = Path(__file__).resolve().parent
_endpoint_data_path = _here / TEST_DATA_FILENAME
with open(_endpoint_data_path, 'r') as f:
    _ENDPOINT_DATA = json.load(f)

# Reusable parametrize args
_PARAM_CASES = _ENDPOINT_DATA
_PARAM_IDS = [f"scenario_{i}" for i, _ in enumerate(_ENDPOINT_DATA)]

# Initialize SwaggerSchemaValidator
validator = SwaggerSchemaValidator(API_SPEC_PATH)

@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_get_inventory(api_client, scenario_case, config_test_data):
    """
    Test the /store/inventory endpoint with various scenarios.
    """
    # Setup
    endpoint = '/store/inventory'
    headers = {'Authorization': f"Bearer {api_client.auth['petstore_auth']}"}
    
    # Override default test data with scenario specific data
    test_data = {**config_test_data, **scenario_case}

    # Validate request schema
    validator.validate_json(test_data, 'InventoryRequest')

    # Execute
    response = api_client.get(endpoint, headers=headers)

    # Validate response
    assert response.status_code == scenario_case['statusCode']
    validation_result = validator.validate_schema_by_response(endpoint, 'GET', str(response.status_code), response)
    assert validation_result['valid'], validation_result.get('message', 'Invalid response schema')

    # Additional assertions based on scenario
    if scenario_case['statusCode'] == 200:
        assert isinstance(response.json(), dict), "Response should be a dictionary"
        for key, value in response.json().items():
            assert isinstance(value, int), f"Value for {key} should be an integer"
    else:
        assert response.status_code != 200, "Unexpected success for error scenario"

